using Microsoft.Xna.Framework;
namespace StarlightSyndicateDemo;
public static class MobilityTests
{
 static int checks;static void Check(bool ok,string name){if(!ok)throw new Exception("MOBILITY FAIL: "+name);checks++;Console.WriteLine("MOBILITY PASS: "+name);}
 static bool Near(double a,double b)=>Math.Abs(a-b)<Math.Max(.002,Math.Abs(b)*.00001);
 static MobilityDefinition Def(string kind,int size=0)=>MobilityCatalog.All.Single(d=>d.Kind==kind&&d.Size==size);
 static DemoWorld World(string hull="battleship"){var w=new DemoWorld();w.NewGame(0);w.MobilityTrial(hull);w.Credits=100000;return w;}
 static string Hull(MobilityDefinition d)=>d.Role switch{"Carrier"=>"carrier","CommandDestroyer"=>"command_destroyer","Battlecruiser"=>"battlecruiser","Battleship"=>"battleship","JumpFreighter,CapitalIndustrial"=>"industrial_cap",_=>d.Size switch{1=>"frigate",2=>"cruiser",4=>"carrier",_=>"battleship"}};
 static int Slot(MobilityDefinition d)=>d.Slot=="medium"?0:6;
 static void Install(DemoWorld w,MobilityDefinition d,int slot=-1)=>Check(w.FitMobility(d.Id,true,slot<0?Slot(d):slot),"Install "+d.Name);
 static void Tackle(DemoWorld w,EwarKind kind,string id="player")=>w.EwarEffects.Add(new(){SourceId="test",TargetId=id,Kind=kind,Key="test"+id,Strength=3,Remaining=100});
 static SpaceTarget Body(string id,string hull,Vector3 point,bool pilot=true){var p=new Ship();p.SetCombatHull(hull);return new(){Id=id,Name=id,Kind=TargetKind.Raider,Profile=p,Training=pilot,Position=point,Shield=100,Armor=100,Hull=100};}
 public static void Run()
