    w.Undock();p.Cap=p.MaxCap;p.Facing=Vector3.UnitX;p.Velocity=new(15,0,0);float cap=p.Cap;var pos=p.Position;Check(w.ToggleMobility(slot),d.Name+" activation");Check(Near(cap-p.Cap,d.Capacitor),d.Name+" paid capacitor");Check(Near(s.CycleLeft,d.Cycle),d.Name+" cycle duration");Check(p.Stat("mass")>=p.Attributes["mass"],d.Name+" drive mass");Check(Near(p.Stat("signatureRadius"),(p.Attributes["signatureRadius"]??0)*(1+d.Signature)),d.Name+" active signature");Check(p.CapacitorUse>=d.Capacitor/d.Cycle,d.Name+" live capacitor use");
    if(d.Skip){Check(!w.ToggleMobility(slot),d.Name+" cannot abort committed spool");Check(!w.SetMobilityOnline(slot,false),d.Name+" cannot offline committed spool");w.UpdateMobility(d.Cycle-.1f);Check(Vector3.Distance(p.Position,pos)<1,d.Name+" no premature jump");w.UpdateMobility(.11f);Check(Near(p.Position.X-pos.X,d.JumpRange),d.Name+" actual spatial jump");Check(Near(p.Velocity.X,15),d.Name+" velocity preserved");Check(!s.Active&&s.Cooldown>0,d.Name+" rearm persists");Check(!w.ToggleMobility(slot),d.Name+" immediate reuse denied");w.EwarEffects.Clear();w.UpdateMobility(s.Cooldown+.01f);p.Cap=p.MaxCap;Check(w.ToggleMobility(slot),d.Name+" rearm expiration");w.LeaveMobilityGrid();}
    else{Check(p.Speed>p.Attributes["maxVelocity"],d.Name+" real speed increase");s.Repeat=false;w.UpdateMobility(d.Cycle+.01f);Check(!s.Active,d.Name+" paid single cycle ends");Check(Near(p.Stat("mass"),p.Attributes["mass"]??0),d.Name+" inactive mass restored");}
    w.Screen=ViewMode.Station;w.LeaveMobilityGrid();
   }
