   Check(w.SetMobilityOnline(slot,false)&&!s.Effective,d.Name+" offline removes effect");Check(w.SetMobilityOnline(slot,true),d.Name+" re-online");Check(w.UnfitMobility(slot)&&w.ItemCount(d.Id,true)==stock,d.Name+" unfit returns stock");
