  var shared=World();Install(shared,Def("MJD",3));Check(!shared.FitMobility(Def("MJD",3).Id,true,1),"One fitted skip drive");shared.Player.SetStat("medSlots",1);Check(shared.EwarFitError(EwarCatalog.All.First(e=>e.Kind==EwarKind.Web),1).Length>0,"EWAR sees occupied mobility medium socket");var sensor=EnhancementCatalog.All.First(d=>d.Kind=="Sensor");Check(shared.EnhancementFitError(sensor,2).Length>0,"Targeting sees occupied mobility medium socket");var defense=DefenseCatalog.All.First(d=>d.Slot=="medium"&&d.Size==1);Check(shared.DefenseFitError(defense,0).Length>0,"Defense sees occupied mobility medium socket");
  var warp=World();double rate=warp.WarpRate,hours=warp.WarpTravelHours,visual=warp.WarpPresentationSeconds;for(int i=6;i<9;i++)Install(warp,Def("Warp"),i);Check(Near(warp.WarpRate,rate+3*Def("Warp").Bonuses["baseWarpSpeedAdd"]),"Warp flat additions combine without percentage stacking");Check(!warp.FitMobility(Def("Warp").Id,true,9),"Three warp accelerator fitted limit");Check(warp.WarpTravelHours<hours&&warp.WarpPresentationSeconds<visual,"Warp speed changes clock and presentation");warp.Undock();double day=warp.Day,travel=warp.WarpTravelHours;warp.WarpNext();Check(warp.Transit!=null&&Near(warp.Day,day),"Actual warp begins alignment without an instant clock jump");warp.CancelWarp();
