  var cargo=World();var expand=Def("Cargo");float basic=cargo.Player.CargoMax;double speed=cargo.Player.Speed,hp=cargo.Player.MaxHull;Install(cargo,expand);Check(cargo.Player.CargoMax>basic&&cargo.Player.Speed<speed&&cargo.Player.MaxHull<hp,"Cargo frame actual hold / speed / hull tradeoffs");cargo.CargoItems.Clear();cargo.Player.Missiles=0;cargo.Player.Ore=basic+10;float stockCargo=cargo.ItemCount(expand.Id,true);Check(!cargo.UnfitMobility(6)&&!cargo.SetMobilityOnline(6,false),"Cargo-dependent removal and offline blocked");Check(!cargo.FitMobility(Def("Nano").Id,true,6)&&cargo.Player.Mobility[6].ModuleId==expand.Id&&cargo.ItemCount(expand.Id,true)==stockCargo,"Capacity-reducing replacement is atomic");cargo.Player.Ore=0;Check(cargo.UnfitMobility(6),"Unload permits hold removal");
  foreach(string kind in new[]{"Cpu","Reactor","Aux","Diagnostic"}){var w=World();var d=Def(kind);Install(w,d);string key=kind=="Cpu"?"cpuOutput":"powerOutput";double used=kind=="Cpu"?w.TotalFitCpu:w.TotalFitPower;w.Player.SetStat(key,kind=="Aux"?used-2:used/1.02);Check(w.MobilityBudgetError().Length==0,kind+" supports otherwise over-budget fit");Check(!w.UnfitMobility(6)&&!w.SetMobilityOnline(6,false),kind+" dependent removal blocked");}
