   w.EwarEffects.Clear();w.UpdateMobility(w.Player.Mobility[0].Cooldown);w.Player.Cap=w.Player.MaxCap;Check(w.ToggleMobility(0),d.Name+" second spool");point=w.Player.Position;Tackle(w,EwarKind.Scram);w.UpdateMobility(d.Cycle+1);Check(!w.Player.Mobility[0].Active&&Vector3.Distance(point,w.Player.Position)<1,d.Name+" scramble interrupts without teleport");Check(w.Player.Mobility[0].Cooldown>0,d.Name+" interrupted cooldown retained");
   if(d.Kind=="Field"){w.EwarEffects.Clear();w.UpdateMobility(300);w.Player.Cap=w.Player.MaxCap;w.WeaponTestMode=false;w.SystemId=DemoWorld.Systems.First(sys=>sys.Security>=.5).Id;Check(!w.ToggleMobility(0),d.Name+" high-security field blocked");w.SystemId=DemoWorld.Systems.First(sys=>sys.Security<.5).Id;Check(w.ToggleMobility(0),d.Name+" low-security field allowed");}
  }
