   var npc=Body("npc","frigate",origin+new Vector3(0,0,1),false);w.Targets.Add(npc);var tackled=Body("tackled","frigate",origin+new Vector3(0,0,2));w.Targets.Add(tackled);Tackle(w,EwarKind.Scram,tackled.Id);
