   Check(w.ToggleMobility(0),d.Name+" passenger activation");w.UpdateMobility(d.Cycle);Check(w.Targets.Count(t=>t.Id.StartsWith("pilot")&&t.Position.X>origin.X+1000)==d.ShipCap-(size==4?1:0),d.Name+" capped subcapital passengers");Check(w.Targets.Count(t=>t.Id.StartsWith("capital")&&t.Position.X>origin.X+1000)==d.CapitalCap,d.Name+" capped capital passengers");Check(Near(npc.Position.X,origin.X)&&Near(tackled.Position.X,origin.X)&&Near(far.Position.X,origin.X),d.Name+" NPC / scramble / radius exclusions");Check(w.MissilesInFlight[0].Position.X>origin.X+1000&&Near(w.MissilesInFlight[1].Position.X,origin.X),d.Name+" bomb moved / ordinary missile excluded");if(size==1)Check(Near(command.Position.X,origin.X),"Ordinary field excludes industrial command");else Check(w.EwarFor("player").Scrammed&&w.EwarEffects.Any(e=>e.TargetId=="pilot0"&&Near(e.Remaining,d.PostScram)),"Capital field applies post-jump scramble");
  }
